{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "1BnTIQ, a carboxamide-containing cyclic molecule, was detected throughout monkey brain after systemic administration, demonstrating that this scaffold can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "PNU282987, a chloro-substituted benzamide, showed good brain penetration after intravenous injection, supporting CNS access for related amide/chlorophenyl compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "[11C]SA6298, which contains a 3,4-dichlorophenyl group, showed high brain uptake on PET in cat, directly supporting that dichlorophenyl-containing amides can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "ICI 197067, a dichlorophenylacetamide, reached quantifiable brain concentrations and produced centrally mediated effects, supporting CNS access for dichlorophenyl amide analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Cyheptamide, a primary carboxamide, showed brain levels similar to serum in rats, supporting that primary amide-containing molecules can readily cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "EVT 301, a carboxamide anilide, achieved >90% brain MAO-B occupancy in humans, demonstrating meaningful CNS access for an amide-anilide chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful CNS penetration across species, including direct brain detection, PET uptake, and central target occupancy; the query's amide/chlorophenyl scaffold aligns with these CNS-penetrant chemotypes, so predict pass.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule; evidence is analogical.",
    "Efflux-transporter status for the query is not directly assessed.",
    "Most evidence is qualitative brain uptake rather than quantitative unbound brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

